#define RTR_NVECTORS (sizeof rtr_vectors / sizeof rtr_vectors[0])
#define RTR_MAXLEN 1000000u

static uint8_t *g_buf;

static void vectors_oneshot(void) {
    for (size_t i = 0; i < RTR_NVECTORS; i++) {
        rtr_vector const *v = &rtr_vectors[i];
        RTR_CHECK_EQ_MSG(rtr_hash64_seed(g_buf, v->len, v->seed), v->expect,
                         "rtr_hash64_seed");
    }
}

/* rtr_hash64 must be exactly the seed-0 case, not a separate code path. */
static void vectors_unseeded_alias(void) {
    for (size_t i = 0; i < RTR_NVECTORS; i++) {
        rtr_vector const *v = &rtr_vectors[i];
        if (v->seed != 0) continue;
        RTR_CHECK_EQ_MSG(rtr_hash64(g_buf, v->len), v->expect, "rtr_hash64");
    }
}

/* The vectors are the strongest oracle we have, so run them on every path. */
static void vectors_every_level(void) {
    int levels[8];
    size_t const n = rtr_collect_levels(levels, 8);

    for (size_t l = 0; l < n; l++) {
        if (!RTR_CHECK(rtr_hash_force_level((rtr_simd_level_t)levels[l]) == 0))
            continue;
        for (size_t i = 0; i < RTR_NVECTORS; i++) {
            rtr_vector const *v = &rtr_vectors[i];
            RTR_CHECK_EQ_MSG(rtr_hash64_seed(g_buf, v->len, v->seed), v->expect,
                             rtr_hash_level_str((rtr_simd_level_t)levels[l]));
        }
    }
    rtr_hash_reset_level();
}

/* Streaming must land on the published value too, not merely on our own. */
static void vectors_streaming(void) {
    rtr_hash_state_t *st = rtr_hash_create();

    if (!RTR_CHECK(st != NULL)) return;
    for (size_t i = 0; i < RTR_NVECTORS; i++) {
        rtr_vector const *v = &rtr_vectors[i];
        size_t const chunk = 97; /* coprime with every boundary in the design */

        RTR_CHECK(rtr_hash_reset(st, v->seed) == 0);
        for (size_t off = 0; off < v->len; off += chunk) {
            size_t const n = v->len - off < chunk ? v->len - off : chunk;
            RTR_CHECK(rtr_hash_update(st, g_buf + off, n) == 0);
        }
        RTR_CHECK_EQ_MSG(rtr_hash_digest(st), v->expect, "streaming digest");
    }
    rtr_hash_destroy(st);
}

int main(void) {
    printf("test_vectors (oracle: upstream xxHash v0.8.3)\n");
    rtr_print_levels();

    g_buf = (uint8_t *)malloc(RTR_MAXLEN);
    if (g_buf == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    rtr_fill_test_buffer(g_buf, RTR_MAXLEN);

    RTR_RUN(vectors_oneshot);
    RTR_RUN(vectors_unseeded_alias);
    RTR_RUN(vectors_every_level);
    RTR_RUN(vectors_streaming);

    free(g_buf);
    return RTR_REPORT("test_vectors");
}
